// defaultAttributes returns the allowed attribute keys configured by the
// experimental WithDefaultAttributes option, if it was passed in opts.
//
// A nil return value indicates the option was not provided and no attribute
// filtering should be applied. A non-nil (possibly empty) slice indicates the
// option was provided and only the returned keys are allowed.
func defaultAttributes[T any](opts []T) []attribute.Key {
	var keys []attribute.Key
	var found bool
	for _, o := range opts {
		if exp, ok := any(o).(interface{ AllowedKeys() []attribute.Key }); ok {
			found = true
			keys = append(keys, exp.AllowedKeys()...)
		}
	}
	if found && keys == nil {
		return []attribute.Key{}
	}
	return keys
}

